        if (!$statsDb->schema()->tableExists('bot_useragents')) {
            try {
                $statsDb
                    ->schema()
                    ->createTable('bot_useragents')
                    ->string('useragent', 255)
                    ->primaryKey('useragent')
                    ->engine('MyISAM')
                    ->charset('utf8')
                    ->execute();
            } catch (\Exception $e) {
